//测试是否需要重新获取页面内容，如果需要，则尝试延迟4倍延迟分级标准时间再次获取，最多重复5次
const reFetchTest = (java, baseUrl, result, type) => {
	L(java,64,`${baseUrl} 判断是否请求超时`);
	let reFetchTime = 0;
	let contentRule = "#ChapterView@div.bd@div.page-content@html";
	if(type === "目录"){
		contentRule = ".chapter-list.1@li@a@text";
	}
	//超时处理
	while((result == "" || java.getString("tag.title@text") == "网站请求超时" || java.getString(contentRule, result) == "") && reFetchTime < 5){
		L(java,64,`${baseUrl} 在${type}解析时出现超时，延时后重新获取第${++reFetchTime}次！！`);
		let ms_Now = Date.now();
		let ms_End = ms_Now + speedGrading * 4;
		while(ms_Now < ms_End){
			ms_Now = Date.now();
		}
		L(java,64,baseUrl + " 延时结束，开始重新获取！！");
		result = java.connect(baseUrl).body();
	}
