		case 2:
			pct = 0.46;
			break;
		case 3:
			pct = 0.29;
			break;
		case 4:
			pct = 0.2;
			break;
		case 5:
			pct = 0.14;
			break;
		case 9:
			pct = 0.6;
			break;
	}
