	var di = {};
	di.modual = modual;
	di.type = "title";
	di.name = name;
	return creatEle(di);
}
//创建链接（仅限发现界面）
const newUrl = (name,url,cols) => {
	var di = {};
	di.modual = "disc";
	di.type = "url";
	di.name= name;
	di.url= url;
	di.cols= cols;
	return creatEle(di);
}
//创建按钮（执行func）
const newButton = (name,modual,func,cols) => {
	var di = {};
	di.modual = modual;
	di.type = "button";
	di.name = name;
	di.func= func;
	di.cols = cols;
	return creatEle(di);
}
//创建强制换行按钮（执行func）
const newButtonW = (name,modual,func,cols) => {
	var di = {};
	di.modual = modual;
	di.type = "buttonW";
	di.name = name;
	di.func= func;
	di.cols = cols;
	return creatEle(di);
}
//创建文本输入（⚠️输入完毕执行func没有测试过）
const newText = (name,modual,func,cols) => {
	var di = {};
	di.modual = modual;
	di.type = "text";
	di.name = name;
	di.func= func;
	di.cols= cols;
	return creatEle(di);
